source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # The five-cell horizontal object is the stamp to copy.
    stamp = None
    stamp_cells = set()
    for r, row in enumerate(grid):
        for c in range(w - 4):
            vals = row[c:c + 5]
            if all(v != bg for v in vals):
                stamp = vals[:]
                stamp_cells = {(r, x) for x in range(c, c + 5)}
                break
        if stamp is not None:
            break
    out = [row[:] for row in grid]
    if stamp is None:
        return out
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r, c) not in stamp_cells:
                left = c - 2
                for k, value in enumerate(stamp):
                    x = left + k
                    if 0 <= x < w:
                        out[r][x] = value
    return out
